import type { ExpoConfig } from 'expo/config'
import { withAndroidManifest, type ConfigPlugin } from 'expo/config-plugins'

// Shared with the Profile screen, which displays it.
import versionInfo from './src/version.json'

// Single source of truth for the native app config. android/ and ios/ are
// generated by `expo prebuild` / EAS and gitignored, so settings such as
// newArchEnabled must be changed here, never in generated gradle files.
//
// Cleartext (plain http) traffic is refused in preview/production builds. The
// prebuild template's debug manifest already re-enables it (tools:replace) for
// debug variants, so dev clients can still reach a local http API; EAS
// `development` builds (or APP_VARIANT=development) also allow it explicitly.
// Expo has no app-config key for this (`android.usesCleartextTraffic` was
// silently ignored), hence the small manifest plugin below.
const isDevelopmentBuild =
  process.env.EAS_BUILD_PROFILE === 'development' || process.env.APP_VARIANT === 'development'

const withCleartextPolicy: ConfigPlugin<boolean> = (expoConfig, allowCleartext) =>
  withAndroidManifest(expoConfig, (mod) => {
    const application = mod.modResults.manifest.application?.[0]
    if (application) {
      application.$['android:usesCleartextTraffic'] = allowCleartext ? 'true' : 'false'
    }
    return mod
  })

const BRAND_PRIMARY = '#0A5C6E' // colors.primary in src/theme.ts

const config: ExpoConfig = {
  name: 'MiqorAI Patient',
  slug: 'miqorai-patient-mobile',
  version: versionInfo.version,
  orientation: 'portrait',
  userInterfaceStyle: 'light',
  newArchEnabled: false,
  icon: './assets/icon.png',
  splash: {
    image: './assets/splash-icon.png',
    resizeMode: 'contain',
    backgroundColor: BRAND_PRIMARY,
  },
  ios: {
    supportsTablet: false,
    bundleIdentifier: 'com.miqorai.patient',
  },
  android: {
    adaptiveIcon: {
      foregroundImage: './assets/adaptive-icon.png',
      backgroundColor: BRAND_PRIMARY,
    },
    package: 'com.miqorai.patient',
    versionCode: 1,
  },
  web: {
    favicon: './assets/icon.png',
  },
  plugins: ['expo-secure-store'],
}

export default withCleartextPolicy(config, isDevelopmentBuild)
